<script setup lang="ts">
import {displayText,displayJson,initials} from "../stores/presentation"
import {ref,onMounted,onUnmounted,nextTick} from 'vue'
import {api as staffApi} from '../api'
const props=defineProps<{caseId:string;revision:number;disabled:boolean;borrower?:boolean;reviewOnly?:boolean}>(),emit=defineEmits(['changed','notes'])
async function api(path:string,body?:any){if(!props.borrower)return staffApi(path,body);const r=await fetch('/api'+path,{method:body===undefined?'GET':'POST',headers:{Authorization:'Bearer '+(sessionStorage.getItem('borrower_token')||''),...(body===undefined?{}:{'Content-Type':'application/json'})},body:body===undefined?undefined:JSON.stringify(body)});const d=await r.json().catch(()=>{throw Error('Service unavailable. Please try again shortly.')});if(!r.ok)throw Error(d.detail||'Interview unavailable');return d}
const camera=ref(false),preview=ref<HTMLVideoElement|null>(null),speaking=ref(false)
let cameraStream:MediaStream|undefined
function closeCamera(){cameraStream?.getTracks().forEach(t=>t.stop());cameraStream=undefined;camera.value=false}
async function toggleCamera(){if(camera.value){closeCamera();return}try{cameraStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user'},audio:false});camera.value=true;await nextTick();if(preview.value){preview.value.srcObject=cameraStream;await preview.value.play()}}catch{closeCamera();error.value='Camera unavailable. Allow camera permission, or continue with audio.'}}
const mode=ref('mock'),configured=ref(false),language=ref('en-IN'),consent=ref(false),active=ref(false),ready=ref(false),recording=ref(false),completed=ref(false),question=ref(''),answer=ref(''),transcript=ref(''),error=ref(''),turns=ref<any[]>([]),history=ref<any[]>([]),busy=ref(false)
let ws:WebSocket|undefined,context:AudioContext|undefined,stream:MediaStream|undefined,processor:AudioWorkletNode|undefined,source:MediaStreamAudioSourceNode|undefined,playAt=0
const playing=new Set<AudioBufferSourceNode>()
async function load(){try{const r=await api('/applications/'+props.caseId+'/voice-sessions');mode.value=r.mode;configured.value=r.configured;history.value=r.items}catch(e){error.value=(e as Error).message}}
function releaseAudio(){recording.value=false;processor?.disconnect();source?.disconnect();stream?.getTracks().forEach(t=>t.stop());for(const s of playing){try{s.stop()}catch{}}playing.clear();speaking.value=false;closeCamera();if(context&&context.state!=='closed')void context.close();context=undefined;processor=undefined;stream=undefined;playAt=0}
function stop(){recording.value=false;processor?.port.postMessage({record:false});if(ws?.readyState===WebSocket.OPEN)ws.send(JSON.stringify({type:'stop'}));else{ws?.close();releaseAudio();active.value=false}}
async function start(){busy.value=true;error.value='';completed.value=false;transcript.value='';answer.value='';turns.value=[];try{
 if(mode.value==='sarvam'){
  if(!navigator.mediaDevices?.getUserMedia)throw Error('Microphone requires localhost or HTTPS and a supported browser.');
  context=new AudioContext();await context.resume();await context.audioWorklet.addModule('/pcm-capture.js');stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true},video:false});source=context.createMediaStreamSource(stream);processor=new AudioWorkletNode(context,'pcm-capture');processor.port.onmessage=e=>{if(ws?.readyState===WebSocket.OPEN){if(ws.bufferedAmount>64000){error.value='Connection is too slow; session stopped.';stop();return}ws.send(e.data)}};source.connect(processor);processor.connect(context.destination);
 }
 const d=await api('/applications/'+props.caseId+'/voice-sessions',{revision:props.revision,language:language.value,consent:consent.value});
 ws=new WebSocket((location.protocol==='https:'?'wss://':'ws://')+location.host+d.socket_path);active.value=true;ready.value=false;
 ws.onopen=()=>ws?.send(JSON.stringify({session_id:d.session_id,ticket:d.ticket}));
 ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.type==='ready')ready.value=true;if(m.type==='question'){question.value=m.text;transcript.value='';answer.value=''}if(m.type==='transcript')transcript.value=m.text;if(m.type==='answer_saved')turns.value=m.turns;if(m.type==='completed'){completed.value=true;recording.value=false;processor?.port.postMessage({record:false})}if(m.type==='validation'||m.type==='error')error.value=m.message;if(m.type==='saved'){active.value=false;void load();emit('changed')}
 if(m.type==='audio'&&context){const b=atob(m.pcm),data=new DataView(new ArrayBuffer(b.length));for(let i=0;i<b.length;i++)data.setUint8(i,b.charCodeAt(i));const audio=context.createBuffer(1,b.length/2,m.sample_rate),samples=audio.getChannelData(0);for(let i=0;i<samples.length;i++)samples[i]=data.getInt16(i*2,true)/32768;const node=context.createBufferSource();node.buffer=audio;node.connect(context.destination);playAt=Math.max(playAt,context.currentTime);if(playAt-context.currentTime>15){error.value='Audio playback fell behind; stopping session.';stop();return}playing.add(node);speaking.value=true;node.onended=()=>{playing.delete(node);speaking.value=playing.size>0};node.start(playAt);playAt+=audio.duration;}
 };
 ws.onerror=()=>{error.value='Voice connection failed. Check the server and retry.';releaseAudio();active.value=false};ws.onclose=()=>{releaseAudio();active.value=false;ready.value=false;void load()};
 }catch(e){error.value=(e as Error).message;releaseAudio();active.value=false}finally{busy.value=false}}
function toggleRecord(){recording.value=!recording.value;processor?.port.postMessage({record:recording.value})}
function submit(){if(ws?.readyState!==WebSocket.OPEN)return;error.value='';ws.send(JSON.stringify({type:'answer',text:mode.value==='mock'?answer.value:''}))}
function useNotes(v:any){emit('notes',('Voice interview '+v.id+' (unverified transcript; officer reviewed):\n'+v.turns.map((t:any)=>t.question+'\n'+t.answer).join('\n\n')).slice(0,2000))}
onMounted(load);onUnmounted(()=>{ws?.close();releaseAudio()})
</script>
<template><section class="panel voice-panel"><div class="section-title"><h2>{{reviewOnly?'Borrower conversation':'Meet your application assistant.'}}</h2><span class="badge">{{displayText(mode==='sarvam'?'Voice assistant':'Written interview')}}</span></div><p v-if="reviewOnly">The borrower completes this conversation from their application. Review their saved answers below.</p><p v-else>A short, guided conversation about the person, the business and the plan. Your credit officer reviews the answers alongside the application.</p><p v-if="mode==='sarvam'" class="notice">With consent, microphone audio is sent to Sarvam for speech recognition and generated prompts use Sarvam speech. Transcript text is saved with the case; raw audio is not stored by this app. </p><p v-else class="notice">Capture the interview in writing. Answers are saved for the credit officer to review.</p><p v-if="error" role="alert" class="error">{{displayText(error)}}</p><div v-if="!reviewOnly" class="conversation-stage"><div class="assistant-stage"><div class="assistant-orb" :class="{speaking}"><span>✦</span></div><h3>Application assistant</h3><p role="status">{{speaking?'Speaking…':recording?'Listening to you…':active?'Ready when you are':'Let’s talk about your business'}}</p><div class="voice-waves" :class="{moving:speaking||recording}"><i v-for="n in 15" :style="{'--i':n}"></i></div></div><div class="camera-stage"><video v-show="camera" ref="preview" autoplay muted playsinline></video><div v-if="!camera"><span class="camera-placeholder">◎</span><p>Your camera is off</p></div><button type="button" :aria-pressed="camera" @click="toggleCamera">{{camera?'Turn camera off':'Turn camera on'}}</button></div><small class="camera-note">Camera preview stays on your device. No video is uploaded, recorded or used to verify identity.</small></div><div v-if="!active&&!reviewOnly"><label>Interview language<select v-model="language"><option value="en-IN">English (India)</option><option value="hi-IN">Hindi</option><option value="ta-IN">Tamil</option></select></label><label class="checkbox"><input type="checkbox" v-model="consent">Participant agrees to this {{displayText(mode==='sarvam'?'voice':'written')}} interview and saving its transcript.</label><button class="primary" :disabled="!consent||!configured||disabled||busy" @click="start">{{displayText(busy?'Connecting…':'Start interview')}}</button><small v-if="!configured">Voice is currently unavailable. Contact your administrator or record the interview manually.</small></div><div v-else-if="!reviewOnly"><strong>{{displayText(ready?question:'Preparing your interview…')}}</strong><template v-if="!completed"><label v-if="mode==='mock'">Your answer<textarea v-model="answer" maxlength="2000"></textarea></label><template v-else><p>Listen to the question, record your answer, then stop recording. Wait for the final transcript before submitting. This is a guided turn-by-turn interview.</p><button @click="toggleRecord" :disabled="!ready">{{displayText(recording?'Stop recording':'Record answer')}}</button><p class="notice">{{displayText(transcript||'Transcript will appear here.')}}</p></template><button class="primary" @click="submit" :disabled="!ready||recording||!(mode==='mock'?answer.trim():transcript.trim())">Submit answer</button></template><p v-else class="notice">All three answers captured. Finish the session to save them for review.</p> <button @click="stop">{{displayText(completed?'Finish and save transcript':'Stop interview')}}</button><ol><li v-for="t in turns">{{displayText(t.answer)}}</li></ol></div><details v-if="history.length"><summary>Saved voice sessions ({{displayText(history.length)}})</summary><div v-for="v in history" class="finding"><strong>{{displayText(v.status)}} · {{displayText(v.language)}} · {{v.mode==='sarvam'?'Voice':'Written'}}</strong><small>{{displayText(v.created_at)}} · {{displayText(v.id)}} {{displayText(v.stale?'· stale case revision':'')}}</small><p v-for="t in v.turns"><b>{{displayText(t.question)}}</b><br>{{displayText(t.answer)}}</p><button v-if="v.status==='completed'&&!v.stale" :disabled="active||disabled" @click="useNotes(v)">Copy transcript to officer notes</button></div></details></section></template>
